	type GenerationRecord,
	type PresentHead,
	type StoreResult,
} from "@ts-drp/storage";
import { fork } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
